// ContinuousAggregateManager настраивает непрерывную инкрементальную агрегацию
type ContinuousAggregateManager struct {
	db *sql.DB
}

func (m *ContinuousAggregateManager) GenerateCaggDDL() string {
	return `
-- 1. Создание непрерывного материализованного представления (Continuous Aggregate)
CREATE MATERIALIZED VIEW device_metrics_hourly
WITH (timescaledb.continuous) AS
SELECT 
    time_bucket('1 hour', time) AS bucket,
    device_id,
    AVG(temperature) AS avg_temp,
    MAX(temperature) AS max_temp,
    MIN(temperature) AS min_temp,
    COUNT(*) AS total_samples
FROM device_metrics
GROUP BY bucket, device_id
WITH NO DATA;

-- 2. Настройка политики автоматического фонового обновления (каждые 30 минут)
SELECT add_continuous_aggregate_policy('device_metrics_hourly',
    start_offset => INTERVAL '1 month',
    end_offset => INTERVAL '1 hour',
    schedule_interval => INTERVAL '30 minutes');
`
}

func main() {
	fmt.Println("=== Continuous Aggregates в TimescaleDB ===")
	mgr := &ContinuousAggregateManager{}
	fmt.Println(mgr.GenerateCaggDDL())
	fmt.Println("Преимущество: Дашборд Grafana читает предварительно вычисленные 1-часовые агрегаты")
	fmt.Println("из материализованного представления за 2 мс вместо тяжелого скана миллиардов строк.")
}

theory:
Удаление старых данных через стандартную команду SQL `DELETE FROM metrics WHERE time < NOW() - INTERVAL '14 days'` в высоконагруженных системах приводит к катастрофе:
1) Сканируются миллионы строк;
2) Каждая удаленная строка генерирует запись в журнале предзаписи WAL;
3) Создается огромное количество 'мертвых' кортежей (Dead Tuples), приводя к раздуванию (Table Bloat) и перегрузке фонового процесса VACUUM.

В TimescaleDB удаление данных реализовано через **Retention Policies** на уровне чанков. Поскольку данные разделены на физические чанки по дням, удаление данных старше 14 дней сводится к вызову `DROP TABLE _timescaledb_internal._hyper_1_chunk_old`. Это операция изменения метаданных: она выполняется за несколько миллисекунд, освобождает гигабайты дискового пространства мгновенно и не генерирует WAL-нагрузки.

